    internal partial class ClassBinaryCreateTranslation : FalloutNVMajorRecordBinaryCreateTranslation
    {
        public new static readonly ClassBinaryCreateTranslation Instance = new ClassBinaryCreateTranslation();

        public override RecordType RecordType => RecordTypes.CLAS;
        public static ParseResult FillBinaryRecordTypes(
            IClassInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.FULL:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.Name = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)Class_FieldIndex.Name;
                }
                case RecordTypeInts.DESC:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.Description = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.DL,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)Class_FieldIndex.Description;
                }
                case RecordTypeInts.ICON:
                {
                    item.Icons = Mutagen.Bethesda.FalloutNV.Icons.CreateFromBinary(
                        frame: frame,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Class_FieldIndex.Icons;
                }
                case RecordTypeInts.DATA:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    var dataFrame = frame.SpawnWithLength(contentLength);
                    if (dataFrame.Remaining < 4) return null;
                    item.TagSkill1 = dataFrame.ReadInt32();
                    if (dataFrame.Remaining < 4) return null;
                    item.TagSkill2 = dataFrame.ReadInt32();
                    if (dataFrame.Remaining < 4) return null;
                    item.TagSkill3 = dataFrame.ReadInt32();
                    if (dataFrame.Remaining < 4) return null;
                    item.TagSkill4 = dataFrame.ReadInt32();
                    if (dataFrame.Remaining < 4) return null;
                    item.Flags = dataFrame.ReadUInt32();
                    if (dataFrame.Remaining < 4) return null;
                    item.Services = dataFrame.ReadUInt32();
                    if (dataFrame.Remaining < 1) return null;
                    item.Teaches = dataFrame.ReadUInt8();
                    if (dataFrame.Remaining < 1) return null;
                    item.MaxTrainingLevel = dataFrame.ReadUInt8();
                    if (dataFrame.Remaining < 2) return null;
                    item.Unknown = dataFrame.ReadUInt16();
                    return (int)Class_FieldIndex.Unknown;
                }
                case RecordTypeInts.ATTR:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    var dataFrame = frame.SpawnWithLength(contentLength);
                    if (dataFrame.Remaining < 7) return null;
                    Mutagen.Bethesda.Plugins.Binary.Translations.DictBinaryTranslation<Byte>.Instance.Parse<Attribute>(
                        reader: frame,
                        item: item.Attributes,
                        transl: ByteBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse);
                    return (int)Class_FieldIndex.Attributes;
                }
                default:
                    return FalloutNVMajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                        item: item,
                        frame: frame,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        nextRecordType: nextRecordType,
                        contentLength: contentLength,
                        translationParams: translationParams.WithNoConverter());
            }
        }

    }

